/** Os arquivos de `templates/` e `examples/` do repositório, pelo caminho. */
export const TEMPLATES_FILES: Record<string, string> = {
  "templates/en/explanation/adr.md": "---\ntemplate:\n  version: 1\n  name: Architecture decision record (ADR)\n  description: Record an architecture decision\n  category: explanation\n  example: explanation/adr.md\n  folder: adr\n  numbered: true\n  fields:\n    status:\n      prompt: Status\n      default: \"Proposed\"\n---\n\n# {{title}}\n\nStatus: {{status}}\n\nDate: {{date}}\n\n## Context\n\nThe situation that requires a decision, and the forces at play.\n\n## Decision\n\nWhat was decided, in one or two sentences.\n\n## Consequences\n\n- What gets easier\n- What gets harder, and what we accept\n\n## Alternatives considered\n\n- Alternative: why it was not chosen\n",
  "templates/en/explanation/architecture.md": "---\ntemplate:\n  version: 1\n  name: Architecture\n  description: How the system is today, and why\n  category: explanation\n  example: explanation/architecture.md\n---\n\n# {{title}}\n\nHow the system is built today and why, for whoever changes it next.\n\n## Context\n\nThe problem the system solves and its main users.\n\n## Overview\n\nA diagram of the main parts, and one sentence about each.\n\n## Components\n\n- Component: what it does and what it owns\n\n## Data\n\n- Where the data lives, who writes it and who reads it\n\n## Integrations\n\n- External systems: what goes in and out, and what happens when they fail\n\n## Important decisions\n\n- Each decision with a link to its ADR\n\n## Known risks\n\n- Risk: impact, and what is being done about it\n",
  "templates/en/explanation/postmortem.md": "---\ntemplate:\n  version: 1\n  name: Postmortem\n  description: Blameless review of an incident\n  category: explanation\n  example: explanation/postmortem.md\n  folder: postmortems\n---\n\n# {{title}}\n\nWritten on {{date}}. This review looks for causes, not culprits.\n\n## Summary\n\nWhat happened, in two or three sentences.\n\n## Impact\n\nWho was affected, how and for how long.\n\n## Timeline\n\n- 10:00 The alert fires.\n- 10:05 Someone starts investigating.\n- 10:30 The service is back to normal.\n\n## Root cause\n\nWhy it happened, going past the first answer.\n\n## What went well\n\n- Something that helped\n\n## What did not go well\n\n- Something that got in the way\n\n## Actions\n\n- [ ] Action, owner and due date\n",
  "templates/en/explanation/rfc.md": "---\ntemplate:\n  version: 1\n  name: RFC / design doc\n  description: A proposal before the decision (the ADR records the result)\n  category: explanation\n  example: explanation/rfc.md\n  folder: rfcs\n  numbered: true\n  fields:\n    status:\n      prompt: Status\n      default: \"Draft\"\n---\n\n# {{title}}\n\nStatus: {{status}}\n\nAuthor: {{owner}} · Date: {{date}}\n\n## Summary\n\nThe proposal in two or three sentences.\n\n## Problem\n\nWhat is wrong today, and who it affects. Numbers help: errors, time, cost.\n\n## Proposal\n\nHow it would work. A diagram, the main flows and what changes for each team.\n\n## Alternatives\n\n| Option       | Pros | Cons |\n| ------------ | ---- | ---- |\n| The proposal |      |      |\n| Do nothing   |      |      |\n\n## Risks and open questions\n\n- What could go wrong, and how we would notice\n- What still needs an answer, and who can answer it\n\n## Rollout\n\nThe steps to get there, and how to go back.\n",
  "templates/en/how-to-guides/guide.md": "---\ntemplate:\n  version: 1\n  name: How-to guide\n  description: Do a known task, step by step\n  category: guide\n  example: how-to-guides/guide.md\n---\n\n# {{title}}\n\nThis guide shows how to do one task. It assumes you know the basics.\n\n## Goal\n\nWhat is done when you finish, in one sentence.\n\n## Before you start\n\n- Access and tools you need\n- Anything that must be true before step 1\n\n## Steps\n\n1. First step: what to do.\n2. Second step: what to do.\n3. Third step: what to do.\n\n## Check that it worked\n\nHow to confirm the result.\n\n## Common problems\n\n- Problem: how to fix it\n",
  "templates/en/how-to-guides/how-to.md": "---\ntemplate:\n  version: 1\n  name: Short how-to\n  description: One task, a few steps, for someone who already knows the basics\n  category: guide\n  example: how-to-guides/how-to.md\n---\n\n# {{title}}\n\nHow to do one thing, in a few steps.\n\n## Steps\n\n1. First step: what to do.\n2. Second step: what to do.\n3. Third step: what to do.\n\n## Check that it worked\n\nHow to see the result.\n",
  "templates/en/how-to-guides/runbook.md": "---\ntemplate:\n  version: 1\n  name: Runbook\n  description: Respond to an alert or run an operations procedure\n  category: guide\n  example: how-to-guides/runbook.md\n  folder: runbooks\n  fields:\n    alert:\n      prompt: Alert or trigger name\n      default: \"\"\n---\n\n# {{title}}\n\nAlert: {{alert}}\n\nLast reviewed on {{date}} by {{owner}}.\n\n## Impact\n\nWho is affected and how, while the alert is firing.\n\n## Diagnosis\n\n1. Open the dashboard and check the main metric.\n2. Look at the recent deploys.\n3. Search the logs for errors in the last 15 minutes.\n\n```bash\necho \"the command that helps diagnose\"\n```\n\n## Actions\n\n1. The safest action first, and how to confirm it worked.\n2. The next action, if the first one did not solve it.\n\n## How to escalate\n\n- Who to call, and when (for example, after 30 minutes without a fix)\n\n## After it is solved\n\n- Write down what happened in the incident channel\n- Open a postmortem if there was customer impact\n",
  "templates/en/how-to-guides/troubleshooting.md": "---\ntemplate:\n  version: 1\n  name: Troubleshooting\n  description: Frequent symptoms and how to solve them\n  category: guide\n  example: how-to-guides/troubleshooting.md\n---\n\n# {{title}}\n\nFrequent problems with this service, one section per symptom.\n\n## The service does not start\n\n- Probable cause: what usually causes it\n- How to confirm: what to check\n- How to solve: what to do\n\n## Requests are slow\n\n- Probable cause: what usually causes it\n- How to confirm: what to check\n- How to solve: what to do\n\n## Still stuck?\n\nAsk in the team channel, with what you have already tried.\n",
  "templates/en/reference/api-reference.md": "---\ntemplate:\n  version: 1\n  name: API reference\n  description: The contract of an API, for whoever integrates with it\n  category: reference\n  example: reference/api-reference.md\n---\n\n# {{title}}\n\nWhat the API is for, in one or two sentences.\n\n## Authentication\n\nHow to get a token and where to send it.\n\n```bash\ncurl -H \"Authorization: Bearer $TOKEN\" https://api.example.com/v1/items\n```\n\n## Endpoints\n\n### List items\n\n`GET /v1/items`\n\n| Parameter | Type   | Description                |\n| --------- | ------ | -------------------------- |\n| limit     | number | How many items, up to 100  |\n| cursor    | string | Where the next page starts |\n\nExample response:\n\n```json\n{\n  \"items\": [],\n  \"next\": null\n}\n```\n\nErrors: what each error code means here.\n\n## Limits\n\nHow many requests per minute, and what happens above it.\n\n## Versions\n\nHow versions change, and how long an old version keeps working.\n",
  "templates/en/reference/glossary.md": "---\ntemplate:\n  version: 1\n  name: Glossary\n  description: Terms of the domain or of the team, in alphabetical order\n  category: reference\n  example: reference/glossary.md\n---\n\n# {{title}}\n\nTerms used in this documentation, in alphabetical order.\n\n## A\n\n### First term\n\nWhat it means here, in one or two sentences.\nLink to the page that explains more.\n\n## B\n\n### Another term\n\nWhat it means here.\n",
  "templates/en/reference/operations.md": "---\ntemplate:\n  version: 1\n  name: Operations and support\n  description: How the service is run day to day\n  category: reference\n  example: reference/operations.md\n---\n\n# {{title}}\n\nHow {{owner}} runs this service day to day.\n\n## On call and escalation\n\n- On-call rotation: where to see who is on call\n- Escalation: who to call next, and when\n\n## Service levels\n\n| Objective    | Target | Measured by       |\n| ------------ | ------ | ----------------- |\n| Availability | 99.9%  | Successful checks |\n| Latency      | 300 ms | 95th percentile   |\n\n## Alerts\n\n- Each alert with a link to its runbook\n\n## Dashboards and logs\n\n- Main dashboard: link\n- Logs: link and a useful query\n\n## Deploy and rollback\n\n1. How a deploy happens.\n2. How to roll back, and how long it takes.\n\n## Maintenance\n\n- Recurring tasks, with how often and who does them\n",
  "templates/en/reference/release-notes.md": "---\ntemplate:\n  version: 1\n  name: Release notes\n  description: What changed in each version, for the people who use it\n  category: reference\n  example: reference/release-notes.md\n  fields:\n    version:\n      prompt: Version\n      default: \"1.0.0\"\n---\n\n# {{title}}\n\n## {{version}} ({{date}})\n\n### Added\n\n- What is new, from the user's point of view\n\n### Changed\n\n- What works differently now\n\n### Fixed\n\n- What was broken and works now\n\n### Upgrade notes\n\nWhat the user has to do, if anything.\n",
  "templates/en/reference/service-home.md": "---\ntemplate:\n  version: 1\n  name: Service home page\n  description: First page of a component in the catalog\n  category: reference\n  example: reference/service-home.md\n---\n\n# {{title}}\n\nWhat the service does, for whom, in one or two sentences.\n\nThis service is maintained by {{owner}}.\n\n## Who to talk to\n\n- Team: {{owner}}\n- Chat channel: the channel where the team answers questions\n- On call: how to reach the person on call\n\n## Links\n\n- Repository: link to the source code\n- Dashboards: link to the main dashboard\n- Catalog: link to the component in the portal\n\n## Dependencies\n\n- Services this one calls, and what happens when each is down\n- Services that call this one\n\n## Getting started\n\n1. Clone the repository.\n2. Run the service locally (the command and what you should see).\n3. Read the architecture page next.\n",
  "templates/en/reference/wiki-page.md": "---\ntemplate:\n  version: 1\n  name: Wiki page\n  description: A free-form page of a team wiki\n  category: reference\n  example: reference/wiki-page.md\n---\n\n# {{title}}\n\nSummary of the page in one or two sentences.\n\n## Content\n\nThe content of the page.\n\n## Related links\n\n- Related page or document\n\nLast reviewed on {{date}}.\n",
  "templates/en/sites/blank/index.md": "# {{title}}\n",
  "templates/en/sites/blank/template.yml": "version: 1\nname: Blank\ndescription: Only the home page, to start from scratch\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    source: index.md\n",
  "templates/en/sites/golden-path/template.yml": "version: 1\nname: Golden path\ndescription: The recommended path for a kind of service, with a tutorial and troubleshooting\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    page: golden-path\n  - path: tutorial.md\n    title: Getting started\n    page: tutorial\n  - path: troubleshooting.md\n    title: Troubleshooting\n    page: troubleshooting\n",
  "templates/en/sites/service-docs/adr-0001.md": "# {{title}}\n\nStatus: Accepted\n\nDate: {{date}}\n\n## Context\n\nWe need to record the architecture decisions of this service: what was\ndecided, why, and what we accepted with it. Without a record, whoever comes\nlater does not know whether a choice can change or what it costs.\n\n## Decision\n\nEvery important decision becomes an ADR (architecture decision record): a\nshort page in this folder, numbered in the order the decision was made.\n\n## Consequences\n\n- Every ADR has a status, context, decision, consequences and alternatives\n- A revisited decision becomes a new ADR that points to the old one\n- The next ADR comes from the \"New page from template…\" command\n\n## Alternatives considered\n\n- Decisions only in chats and meetings: they fade over time\n- A single architecture document: it mixes the current state with history\n",
  "templates/en/sites/service-docs/template.yml": "version: 1\nname: Service docs\ndescription: Documentation of a service in the catalog, with architecture, operations and decisions\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    page: service-home\n  - path: architecture.md\n    title: Architecture\n    page: architecture\n  - path: operations.md\n    title: Operations and support\n    page: operations\n  - path: adr/0001-record-architecture-decisions.md\n    title: Record architecture decisions\n    section: Decisions\n    source: adr-0001.md\n",
  "templates/en/sites/team-wiki/guides.md": "# {{title}}\n\nGuides explain how to do a known task, step by step: release a version,\nrequest an access, run a team process.\n\n## When to write a guide\n\n- The same question came up twice in the channel\n- A task has steps nobody remembers by heart\n- Someone new will need to do it alone\n\n## How to create a guide\n\nUse \"New page from template…\" in this section and choose the Guide template.\nEach guide says the goal, what you need first, the steps and how to check.\n",
  "templates/en/sites/team-wiki/home.md": "# {{site_name}}\n\nThis is the team wiki: what we need to know to work together, how to do the\neveryday tasks, and what we have already decided.\n\n## How to use this wiki\n\n- Start with the onboarding if you just arrived\n- Look in the guides before asking in the channel\n- Found something wrong or outdated? Fix it right away\n\n## How to write a page\n\n1. In the Documentation section of the Explorer, right-click a section.\n2. Choose \"New page from template…\" and the kind of page.\n3. Send the page for review, like any other change in the repository.\n\n## Who looks after it\n\nThis wiki is maintained by {{owner}}.\n",
  "templates/en/sites/team-wiki/template.yml": "version: 1\nname: Team wiki\ndescription: A team wiki, with onboarding, guides and free-form pages\nfiles:\n  - path: index.md\n    title: Home\n    source: home.md\n  - path: onboarding.md\n    title: Onboarding\n    page: onboarding\n  - path: guides/index.md\n    title: About the guides\n    section: Guides\n    source: guides.md\n  - path: example-page.md\n    title: Example page\n    page: wiki-page\n",
  "templates/en/tutorials/golden-path.md": "---\ntemplate:\n  version: 1\n  name: Golden path\n  description: Document the recommended way to build a type of service\n  category: tutorial\n  example: tutorials/golden-path.md\n---\n\n# {{title}}\n\nThe recommended way to build this type of service, maintained by {{owner}}.\n\n## When to use it\n\n- Situations where this golden path is the right choice\n\n## When not to use it\n\n- Situations where another path fits better, and which one\n\n## What you get\n\n- What comes ready: pipeline, observability, security checks\n- What the platform team keeps up to date for you\n\n## Prerequisites\n\n- Access and tools you need before starting\n\n## Step by step\n\n1. Create the service from the template in the portal.\n2. Configure what the template asks for.\n3. Deploy the first version.\n4. Check the dashboards and alerts.\n\n## Alternatives\n\n- Other paths, and when each one makes sense\n",
  "templates/en/tutorials/onboarding.md": "---\ntemplate:\n  version: 1\n  name: Onboarding\n  description: The first days of someone joining the team or the service\n  category: tutorial\n  example: tutorials/onboarding.md\n---\n\n# {{title}}\n\nWelcome! This page takes you through your first days with {{owner}}.\n\n## Access to request\n\n- [ ] Repository access\n- [ ] Chat channels\n- [ ] Dashboards and logs\n- [ ] Cloud console, if you need it\n\n## Local environment\n\n1. Install the tools (list them with versions).\n2. Clone the repositories.\n3. Run the project and open it in the browser.\n\n## First task\n\nA small, real task that touches the main parts of the code, and who can help.\n\n## People and channels\n\n- Your onboarding buddy: who to ask anything\n- Team channel: where the day-to-day conversation happens\n- Team rituals: stand-up, planning and review, with days and times\n\n## Glossary\n\n- Term: what it means for the team\n",
  "templates/en/tutorials/tutorial.md": "---\ntemplate:\n  version: 1\n  name: Tutorial\n  description: Teach something from scratch, step by step, with a result at the end\n  category: tutorial\n  example: tutorials/tutorial.md\n---\n\n# {{title}}\n\nIn this tutorial you build a small working example and learn the basics.\n\n## What you will build\n\nDescribe the result in one sentence, with a screenshot or the output.\n\n## Before you start\n\n- What the reader needs installed, with versions\n- What the reader needs to know already\n\n## Step 1: prepare the project\n\nWhat to do, in one or two sentences.\n\n```bash\necho \"the command to run\"\n```\n\nYou should see: what the reader sees when it works.\n\n## Step 2: add the first feature\n\nWhat to do and why, in one or two sentences.\n\nYou should see: what changes.\n\n## Step 3: check the result\n\nHow to confirm that everything works.\n\n## Next steps\n\n- A guide for the next task\n- The reference page with every option\n",
  "templates/pt-br/explanation/adr.md": "---\ntemplate:\n  version: 1\n  name: Registro de decisão de arquitetura (ADR)\n  description: Registrar uma decisão de arquitetura\n  category: explanation\n  example: explanation/adr.md\n  folder: adr\n  numbered: true\n  fields:\n    status:\n      prompt: Status\n      default: \"Proposto\"\n---\n\n# {{title}}\n\nStatus: {{status}}\n\nData: {{date}}\n\n## Contexto\n\nA situação que pede uma decisão, e as forças envolvidas.\n\n## Decisão\n\nO que foi decidido, em uma ou duas frases.\n\n## Consequências\n\n- O que fica mais fácil\n- O que fica mais difícil, e o que aceitamos\n\n## Alternativas consideradas\n\n- Alternativa: por que não foi escolhida\n",
  "templates/pt-br/explanation/architecture.md": "---\ntemplate:\n  version: 1\n  name: Arquitetura\n  description: Como o sistema é hoje, e por quê\n  category: explanation\n  example: explanation/architecture.md\n---\n\n# {{title}}\n\nComo o sistema é construído hoje e por quê, para quem for mudá-lo depois.\n\n## Contexto\n\nO problema que o sistema resolve e os principais usuários.\n\n## Visão geral\n\nUm diagrama das partes principais, e uma frase sobre cada uma.\n\n## Componentes\n\n- Componente: o que faz e pelo que responde\n\n## Dados\n\n- Onde os dados ficam, quem grava e quem lê\n\n## Integrações\n\n- Sistemas externos: o que entra e sai, e o que acontece quando falham\n\n## Decisões importantes\n\n- Cada decisão com o link para o ADR dela\n\n## Riscos conhecidos\n\n- Risco: impacto, e o que está sendo feito\n",
  "templates/pt-br/explanation/postmortem.md": "---\ntemplate:\n  version: 1\n  name: Postmortem\n  description: Revisão de um incidente, sem culpados\n  category: explanation\n  example: explanation/postmortem.md\n  folder: postmortems\n---\n\n# {{title}}\n\nEscrito em {{date}}. Esta revisão procura causas, não culpados.\n\n## Resumo\n\nO que aconteceu, em duas ou três frases.\n\n## Impacto\n\nQuem foi afetado, como e por quanto tempo.\n\n## Linha do tempo\n\n- 10:00 O alerta dispara.\n- 10:05 Alguém começa a investigar.\n- 10:30 O serviço volta ao normal.\n\n## Causa raiz\n\nPor que aconteceu, indo além da primeira resposta.\n\n## O que funcionou\n\n- Algo que ajudou\n\n## O que não funcionou\n\n- Algo que atrapalhou\n\n## Ações\n\n- [ ] Ação, responsável e prazo\n",
  "templates/pt-br/explanation/rfc.md": "---\ntemplate:\n  version: 1\n  name: RFC / design doc\n  description: Uma proposta antes da decisão (o ADR registra o resultado)\n  category: explanation\n  example: explanation/rfc.md\n  folder: rfcs\n  numbered: true\n  fields:\n    status:\n      prompt: Status\n      default: \"Rascunho\"\n---\n\n# {{title}}\n\nStatus: {{status}}\n\nAutor: {{owner}} · Data: {{date}}\n\n## Resumo\n\nA proposta em duas ou três frases.\n\n## Problema\n\nO que está errado hoje e quem isso afeta. Números ajudam: erros, tempo, custo.\n\n## Proposta\n\nComo funcionaria. Um diagrama, os fluxos principais e o que muda para cada time.\n\n## Alternativas\n\n| Opção          | Prós | Contras |\n| -------------- | ---- | ------- |\n| A proposta     |      |         |\n| Não fazer nada |      |         |\n\n## Riscos e perguntas em aberto\n\n- O que pode dar errado, e como perceberíamos\n- O que ainda precisa de resposta, e quem pode responder\n\n## Implantação\n\nOs passos para chegar lá, e como voltar atrás.\n",
  "templates/pt-br/how-to-guides/guide.md": "---\ntemplate:\n  version: 1\n  name: Guia\n  description: Fazer uma tarefa conhecida, passo a passo\n  category: guide\n  example: how-to-guides/guide.md\n---\n\n# {{title}}\n\nEste guia mostra como fazer uma tarefa. Ele supõe que você já sabe o básico.\n\n## Objetivo\n\nO que está feito quando você terminar, em uma frase.\n\n## Antes de começar\n\n- Acessos e ferramentas necessários\n- O que precisa ser verdade antes do passo 1\n\n## Passos\n\n1. Primeiro passo: o que fazer.\n2. Segundo passo: o que fazer.\n3. Terceiro passo: o que fazer.\n\n## Como conferir que deu certo\n\nComo confirmar o resultado.\n\n## Problemas comuns\n\n- Problema: como resolver\n",
  "templates/pt-br/how-to-guides/how-to.md": "---\ntemplate:\n  version: 1\n  name: How-to curto\n  description: Uma tarefa só, em poucos passos, para quem já sabe o básico\n  category: guide\n  example: how-to-guides/how-to.md\n---\n\n# {{title}}\n\nComo fazer uma coisa, em poucos passos.\n\n## Passos\n\n1. Primeiro passo: o que fazer.\n2. Segundo passo: o que fazer.\n3. Terceiro passo: o que fazer.\n\n## Como conferir que deu certo\n\nComo ver o resultado.\n",
  "templates/pt-br/how-to-guides/runbook.md": "---\ntemplate:\n  version: 1\n  name: Runbook\n  description: Responder a um alerta ou executar um procedimento de operação\n  category: guide\n  example: how-to-guides/runbook.md\n  folder: runbooks\n  fields:\n    alert:\n      prompt: Nome do alerta ou do gatilho\n      default: \"\"\n---\n\n# {{title}}\n\nAlerta: {{alert}}\n\nRevisado em {{date}} por {{owner}}.\n\n## Impacto\n\nQuem é afetado e como, enquanto o alerta está ativo.\n\n## Diagnóstico\n\n1. Abra o dashboard e confira a métrica principal.\n2. Veja os deploys recentes.\n3. Procure erros nos logs dos últimos 15 minutos.\n\n```bash\necho \"o comando que ajuda no diagnóstico\"\n```\n\n## Ações\n\n1. A ação mais segura primeiro, e como confirmar que funcionou.\n2. A próxima ação, se a primeira não resolver.\n\n## Como escalar\n\n- Quem chamar, e quando (por exemplo, depois de 30 minutos sem solução)\n\n## Depois de resolver\n\n- Registre o que aconteceu no canal do incidente\n- Abra um postmortem se houve impacto para clientes\n",
  "templates/pt-br/how-to-guides/troubleshooting.md": "---\ntemplate:\n  version: 1\n  name: Solução de problemas\n  description: Sintomas frequentes e como resolver\n  category: guide\n  example: how-to-guides/troubleshooting.md\n---\n\n# {{title}}\n\nProblemas frequentes deste serviço, uma seção por sintoma.\n\n## O serviço não sobe\n\n- Causa provável: o que costuma causar\n- Como confirmar: o que conferir\n- Como resolver: o que fazer\n\n## As requisições estão lentas\n\n- Causa provável: o que costuma causar\n- Como confirmar: o que conferir\n- Como resolver: o que fazer\n\n## Ainda sem solução?\n\nPergunte no canal do time, contando o que você já tentou.\n",
  "templates/pt-br/reference/api-reference.md": "---\ntemplate:\n  version: 1\n  name: Referência de API\n  description: O contrato de uma API, para quem integra\n  category: reference\n  example: reference/api-reference.md\n---\n\n# {{title}}\n\nPara que serve a API, em uma ou duas frases.\n\n## Autenticação\n\nComo conseguir um token e onde mandá-lo.\n\n```bash\ncurl -H \"Authorization: Bearer $TOKEN\" https://api.example.com/v1/items\n```\n\n## Endpoints\n\n### Listar itens\n\n`GET /v1/items`\n\n| Parâmetro | Tipo   | Descrição                    |\n| --------- | ------ | ---------------------------- |\n| limit     | number | Quantos itens, até 100       |\n| cursor    | string | Onde começa a próxima página |\n\nExemplo de resposta:\n\n```json\n{\n  \"items\": [],\n  \"next\": null\n}\n```\n\nErros: o que cada código de erro significa aqui.\n\n## Limites\n\nQuantas requisições por minuto, e o que acontece acima disso.\n\n## Versões\n\nComo as versões mudam, e por quanto tempo uma versão antiga continua valendo.\n",
  "templates/pt-br/reference/glossary.md": "---\ntemplate:\n  version: 1\n  name: Glossário\n  description: Termos do domínio ou do time, em ordem alfabética\n  category: reference\n  example: reference/glossary.md\n---\n\n# {{title}}\n\nTermos usados nesta documentação, em ordem alfabética.\n\n## A\n\n### Primeiro termo\n\nO que ele quer dizer aqui, em uma ou duas frases.\nLink para a página que explica mais.\n\n## B\n\n### Outro termo\n\nO que ele quer dizer aqui.\n",
  "templates/pt-br/reference/operations.md": "---\ntemplate:\n  version: 1\n  name: Operação e suporte\n  description: Como o serviço é operado no dia a dia\n  category: reference\n  example: reference/operations.md\n---\n\n# {{title}}\n\nComo {{owner}} opera este serviço no dia a dia.\n\n## Plantão e escalonamento\n\n- Escala de plantão: onde ver quem está de plantão\n- Escalonamento: quem chamar em seguida, e quando\n\n## Níveis de serviço\n\n| Objetivo        | Meta   | Medido por               |\n| --------------- | ------ | ------------------------ |\n| Disponibilidade | 99,9%  | Verificações com sucesso |\n| Latência        | 300 ms | Percentil 95             |\n\n## Alertas\n\n- Cada alerta com o link para o runbook dele\n\n## Dashboards e logs\n\n- Dashboard principal: link\n- Logs: link e uma consulta útil\n\n## Deploy e rollback\n\n1. Como um deploy acontece.\n2. Como voltar a versão, e quanto tempo leva.\n\n## Manutenção\n\n- Tarefas recorrentes, com a frequência e quem faz\n",
  "templates/pt-br/reference/release-notes.md": "---\ntemplate:\n  version: 1\n  name: Notas de versão\n  description: O que mudou em cada versão, para quem usa\n  category: reference\n  example: reference/release-notes.md\n  fields:\n    version:\n      prompt: Versão\n      default: \"1.0.0\"\n---\n\n# {{title}}\n\n## {{version}} ({{date}})\n\n### Novidades\n\n- O que é novo, do ponto de vista de quem usa\n\n### Mudanças\n\n- O que funciona de outro jeito agora\n\n### Correções\n\n- O que estava quebrado e agora funciona\n\n### Como atualizar\n\nO que a pessoa precisa fazer, se precisar.\n",
  "templates/pt-br/reference/service-home.md": "---\ntemplate:\n  version: 1\n  name: Página inicial do serviço\n  description: Primeira página de um componente no catálogo\n  category: reference\n  example: reference/service-home.md\n---\n\n# {{title}}\n\nO que o serviço faz e para quem, em uma ou duas frases.\n\nEste serviço é mantido por {{owner}}.\n\n## Com quem falar\n\n- Time: {{owner}}\n- Canal: o canal onde o time responde dúvidas\n- Plantão: como chamar quem está de plantão\n\n## Links\n\n- Repositório: link para o código\n- Dashboards: link para o dashboard principal\n- Catálogo: link para o componente no portal\n\n## Dependências\n\n- Serviços que este chama, e o que acontece quando cada um cai\n- Serviços que chamam este\n\n## Como começar\n\n1. Clone o repositório.\n2. Rode o serviço localmente (o comando e o que você deve ver).\n3. Leia a página de arquitetura em seguida.\n",
  "templates/pt-br/reference/wiki-page.md": "---\ntemplate:\n  version: 1\n  name: Página de wiki\n  description: Uma página livre da wiki do time\n  category: reference\n  example: reference/wiki-page.md\n---\n\n# {{title}}\n\nResumo da página em uma ou duas frases.\n\n## Conteúdo\n\nO conteúdo da página.\n\n## Links relacionados\n\n- Página ou documento relacionado\n\nÚltima revisão em {{date}}.\n",
  "templates/pt-br/sites/blank/index.md": "# {{title}}\n",
  "templates/pt-br/sites/blank/template.yml": "version: 1\nname: Em branco\ndescription: Só a página inicial, para começar do zero\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    source: index.md\n",
  "templates/pt-br/sites/golden-path/template.yml": "version: 1\nname: Golden path\ndescription: O caminho recomendado para um tipo de serviço, com tutorial e solução de problemas\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    page: golden-path\n  - path: primeiros-passos.md\n    title: Primeiros passos\n    page: tutorial\n  - path: solucao-de-problemas.md\n    title: Solução de problemas\n    page: troubleshooting\n",
  "templates/pt-br/sites/service-docs/adr-0001.md": "# {{title}}\n\nStatus: Aceito\n\nData: {{date}}\n\n## Contexto\n\nPrecisamos registrar as decisões de arquitetura deste serviço: o que foi\ndecidido, por quê e o que aceitamos com isso. Sem registro, quem chega depois\nnão sabe se pode mudar uma escolha nem quanto ela custa.\n\n## Decisão\n\nCada decisão importante vira um ADR (registro de decisão de arquitetura): uma\npágina curta nesta pasta, numerada na ordem em que a decisão foi tomada.\n\n## Consequências\n\n- Todo ADR tem status, contexto, decisão, consequências e alternativas\n- Uma decisão revista vira um ADR novo, que aponta para o antigo\n- O próximo ADR sai do comando \"Nova página a partir de template…\"\n\n## Alternativas consideradas\n\n- Decisões só em conversas e reuniões: somem com o tempo\n- Um documento único de arquitetura: mistura o estado atual com o histórico\n",
  "templates/pt-br/sites/service-docs/template.yml": "version: 1\nname: Docs de serviço\ndescription: Documentação de um serviço do catálogo, com arquitetura, operação e decisões\nfiles:\n  - path: index.md\n    title: \"{{site_name}}\"\n    page: service-home\n  - path: arquitetura.md\n    title: Arquitetura\n    page: architecture\n  - path: operacao-e-suporte.md\n    title: Operação e suporte\n    page: operations\n  - path: adr/0001-registrar-decisoes-de-arquitetura.md\n    title: Registrar decisões de arquitetura\n    section: Decisões\n    source: adr-0001.md\n",
  "templates/pt-br/sites/team-wiki/guides.md": "# {{title}}\n\nOs guias explicam como fazer uma tarefa conhecida, passo a passo: publicar uma\nversão, pedir um acesso, rodar um processo do time.\n\n## Quando escrever um guia\n\n- A mesma pergunta apareceu duas vezes no canal\n- Uma tarefa tem passos que ninguém lembra de cabeça\n- Alguém novo vai precisar fazer isso sozinho\n\n## Como criar um guia\n\nUse \"Nova página a partir de template…\" nesta seção e escolha o template Guia.\nCada guia diz o objetivo, o que precisa antes, os passos e como conferir.\n",
  "templates/pt-br/sites/team-wiki/home.md": "# {{site_name}}\n\nEsta é a wiki do time: o que precisamos saber para trabalhar juntos, como\nfazer as tarefas do dia a dia e o que já decidimos.\n\n## Como usar esta wiki\n\n- Comece pelo onboarding, se você acabou de chegar\n- Procure nos guias antes de perguntar no canal\n- Achou algo errado ou desatualizado? Corrija na hora\n\n## Como escrever uma página\n\n1. Na seção Documentação do Explorer, clique com o botão direito numa seção.\n2. Escolha \"Nova página a partir de template…\" e o tipo de página.\n3. Envie a página para revisão, como qualquer mudança no repositório.\n\n## Quem cuida\n\nEsta wiki é mantida por {{owner}}.\n",
  "templates/pt-br/sites/team-wiki/template.yml": "version: 1\nname: Wiki de time\ndescription: Wiki de um time, com onboarding, guias e páginas livres\nfiles:\n  - path: index.md\n    title: Início\n    source: home.md\n  - path: onboarding.md\n    title: Onboarding\n    page: onboarding\n  - path: guias/index.md\n    title: Sobre os guias\n    section: Guias\n    source: guides.md\n  - path: pagina-de-exemplo.md\n    title: Página de exemplo\n    page: wiki-page\n",
  "templates/pt-br/tutorials/golden-path.md": "---\ntemplate:\n  version: 1\n  name: Golden path\n  description: Documentar o caminho recomendado para construir um tipo de serviço\n  category: tutorial\n  example: tutorials/golden-path.md\n---\n\n# {{title}}\n\nO caminho recomendado para este tipo de serviço, mantido por {{owner}}.\n\n## Quando usar\n\n- Situações em que este golden path é a escolha certa\n\n## Quando não usar\n\n- Situações em que outro caminho serve melhor, e qual\n\n## O que você ganha\n\n- O que já vem pronto: pipeline, observabilidade, verificações de segurança\n- O que o time de plataforma mantém atualizado para você\n\n## Pré-requisitos\n\n- Acessos e ferramentas necessários antes de começar\n\n## Passo a passo\n\n1. Crie o serviço a partir do template no portal.\n2. Configure o que o template pede.\n3. Faça o deploy da primeira versão.\n4. Confira os dashboards e os alertas.\n\n## Alternativas\n\n- Outros caminhos, e quando cada um faz sentido\n",
  "templates/pt-br/tutorials/onboarding.md": "---\ntemplate:\n  version: 1\n  name: Onboarding\n  description: Os primeiros dias de quem chega no time ou no serviço\n  category: tutorial\n  example: tutorials/onboarding.md\n---\n\n# {{title}}\n\nBoas-vindas! Esta página guia os seus primeiros dias com {{owner}}.\n\n## Acessos a pedir\n\n- [ ] Acesso ao repositório\n- [ ] Canais de conversa\n- [ ] Dashboards e logs\n- [ ] Console da nuvem, se precisar\n\n## Ambiente local\n\n1. Instale as ferramentas (liste com as versões).\n2. Clone os repositórios.\n3. Rode o projeto e abra no navegador.\n\n## Primeira tarefa\n\nUma tarefa pequena e real, que passa pelas partes principais do código, e quem\npode ajudar.\n\n## Pessoas e canais\n\n- Sua dupla de onboarding: a quem perguntar qualquer coisa\n- Canal do time: onde acontece a conversa do dia a dia\n- Rituais do time: daily, planejamento e revisão, com dias e horários\n\n## Glossário\n\n- Termo: o que significa para o time\n",
  "templates/pt-br/tutorials/tutorial.md": "---\ntemplate:\n  version: 1\n  name: Tutorial\n  description: Ensinar algo do zero, passo a passo, com um resultado no fim\n  category: tutorial\n  example: tutorials/tutorial.md\n---\n\n# {{title}}\n\nNeste tutorial você monta um exemplo pequeno que funciona e aprende o básico.\n\n## O que você vai construir\n\nDescreva o resultado em uma frase, com uma captura de tela ou a saída.\n\n## Antes de começar\n\n- O que a pessoa precisa ter instalado, com as versões\n- O que a pessoa já precisa saber\n\n## Passo 1: preparar o projeto\n\nO que fazer, em uma ou duas frases.\n\n```bash\necho \"o comando a rodar\"\n```\n\nVocê deve ver: o que aparece quando dá certo.\n\n## Passo 2: adicionar a primeira funcionalidade\n\nO que fazer e por quê, em uma ou duas frases.\n\nVocê deve ver: o que muda.\n\n## Passo 3: conferir o resultado\n\nComo confirmar que tudo funciona.\n\n## Próximos passos\n\n- Um guia para a próxima tarefa\n- A página de referência com todas as opções\n",
  "examples/en/docs/explanation/adr.md": "# ADR 0003: idempotency keys on payment creation\n\nStatus: Accepted\n\nDate: 2026-03-14\n\n## Context\n\nClients retry `POST /v1/payments` when the network fails. Without protection, a retry after a slow answer\ncreated a second payment and charged the customer twice (see the [postmortem](postmortem.md)).\n\n## Decision\n\n`POST /v1/payments` requires an `Idempotency-Key` header. The service stores the key with the request body for\n24 hours. The same key with the same body returns the first payment; with another body, it answers `422`.\n\n## Consequences\n\n- Retries are safe for clients.\n- Every client had to change to send the header (done in Q2).\n- The table of keys grows; a job deletes keys older than 24 hours.\n\n## Alternatives considered\n\n- **Deduplicate by order id:** does not allow two payments for one order (split payments).\n- **Ask the provider to deduplicate:** the provider only offers it for 1 hour.\n",
  "examples/en/docs/explanation/architecture.md": "# Architecture\n\nHow the Payments Service is built today, and why.\n\n## Context\n\nCheckout calls the Payments Service to charge an order. The service talks to the card provider and tells the\norder service the result through the event bus.\n\n## Overview\n\n```mermaid\nflowchart LR\n  Checkout -->|POST /v1/payments| API[Payments API]\n  API --> DB[(PostgreSQL)]\n  API --> Provider[Card provider]\n  Provider -->|webhook| API\n  API -->|payment.paid| Bus[Event bus]\n  Bus --> Orders[Order service]\n```\n\n## Components\n\n- **API:** receives payments, stores them and calls the provider\n- **Webhook handler:** receives the provider's answers and updates the payment\n- **Sync job:** every 5 minutes, asks the provider about payments `pending` for too long\n\n## Data\n\nOne table for payments and one for refunds. Card numbers never reach our database: the checkout sends a token.\n\n## Integrations\n\n| System        | How                | Why                 |\n| ------------- | ------------------ | ------------------- |\n| Card provider | HTTPS and webhooks | Charge and refund   |\n| Event bus     | Publish            | Tell other services |\n\n## Important decisions\n\n- [ADR 0003: idempotency keys](adr.md)\n- [RFC 0007: retries with a queue](rfc.md)\n\n## Known risks\n\n- The provider is a single point of failure; the queue mode only delays payments.\n",
  "examples/en/docs/explanation/postmortem.md": "# Postmortem: duplicate charges on 2026-03-02\n\nA blameless review. The goal is to learn, not to find who to blame.\n\n## Summary\n\nFor 40 minutes, 312 customers were charged twice. All of them were refunded the same day.\n\n## Impact\n\n- 312 duplicate charges, 18,400 USD in total, refunded by 18:00\n- 47 support tickets\n\n## Timeline\n\n| Time  | What happened                                        |\n| ----- | ---------------------------------------------------- |\n| 14:05 | The provider starts answering in 20 s instead of 1 s |\n| 14:06 | Checkout times out at 10 s and retries the payment   |\n| 14:20 | Support reports customers charged twice              |\n| 14:45 | Checkout retries turned off; duplicates stop         |\n| 18:00 | Last refund done                                     |\n\n## Root cause\n\nCheckout retried payments after a timeout, and the Payments Service had no way to tell a retry from a new\npayment.\n\n## What went well and what did not\n\n- Went well: refunds were scripted and finished the same day.\n- Did not: no alert for duplicate charges; support found out first.\n\n## Actions\n\n| Action                                                | Owner    | Due        |\n| ----------------------------------------------------- | -------- | ---------- |\n| Idempotency keys ([ADR 0003](adr.md))                 | Payments | 2026-04-15 |\n| Alert for two payments of the same order in 5 minutes | Payments | 2026-03-20 |\n",
  "examples/en/docs/explanation/rfc.md": "# RFC 0007: retries with a queue when the provider is down\n\nStatus: Accepted\n\nAuthor: Payments team · Date: 2026-08-20\n\n## Summary\n\nWhen the card provider is down, store new payments in a queue and charge them when it comes back, instead of\nfailing them right away.\n\n## Problem\n\nDuring the three provider outages this year, every payment failed and customers had to start over. About 30%\ndid not come back.\n\n## Proposal\n\nA `queue mode` flag. When it is on, `POST /v1/payments` saves the payment as `pending` and answers right away;\na worker charges the queue when the provider answers again, oldest first.\n\n```mermaid\nflowchart LR\n  A[New payment] --> B{Queue mode?}\n  B -- No --> C[Charge now]\n  B -- Yes --> D[Save as pending]\n  D --> E[Worker charges later]\n```\n\n## Alternatives\n\n| Option          | Pros                        | Cons                           |\n| --------------- | --------------------------- | ------------------------------ |\n| Queue mode      | Customers do not start over | Orders wait; more code         |\n| Second provider | No waiting                  | Contract, cost, months of work |\n| Do nothing      | No work                     | Lost sales in every outage     |\n\n## Risks and open questions\n\n- A card can be declined hours later: the order service must handle `payment.failed` late. (Answered: it does.)\n- How long to keep queued payments: 2 hours, then fail them.\n\n## Rollout\n\nBehind the flag, turned on by hand from the runbook. Shipped in 2.3.0.\n",
  "examples/en/docs/how-to-guides/guide.md": "# Rotate the provider API key\n\nThis guide shows how to replace the API key the Payments Service uses to talk to the card provider, without\ndowntime. Do it every 90 days, or right away if the key leaks.\n\n## Goal\n\nThe service uses a new key, and the old key is revoked.\n\n## Before you start\n\n- Admin access to the provider dashboard\n- Write access to the `payments/provider` secret in the vault\n- A quiet moment: avoid the first and last day of the month\n\n## Steps\n\n1. In the provider dashboard, open **API keys** and create a new key named `payments-<date>`.\n\n2. Save it in the vault as the **secondary** key:\n\n   ```bash\n   vault kv patch secret/payments/provider secondary_key=<new key>\n   ```\n\n3. Restart the service. It tries the primary key and falls back to the secondary one:\n\n   ```bash\n   kubectl -n payments rollout restart deployment/payments\n   ```\n\n4. Swap the keys in the vault: the new key becomes `primary_key`, and the old one is removed.\n\n5. Restart the service again and revoke the old key in the provider dashboard.\n\n## Check that it worked\n\nIn the **Payments – provider** dashboard, authentication errors stay at zero and the approval rate does not\ndrop.\n\n## Common problems\n\n- **401 from the provider after step 5:** the old key was revoked before the restart finished. Put it back as\n  `secondary_key` and restart.\n",
  "examples/en/docs/how-to-guides/how-to.md": "# Refund a payment\n\nHow to refund a payment, fully or in part, from the command line.\n\n## Steps\n\n1. Find the payment by the order:\n\n   ```bash\n   paymentsctl find --order order-1\n   ```\n\n2. Refund it. Leave out `--amount` to refund everything:\n\n   ```bash\n   paymentsctl refund pay_123 --amount 500 --reason \"damaged item\"\n   ```\n\n3. Tell the customer support agent the refund id (it starts with `ref_`).\n\n## Check that it worked\n\n`paymentsctl show pay_123` lists the refund with status `succeeded`. The money reaches the customer in 5 to\n10 business days.\n",
  "examples/en/docs/how-to-guides/runbook.md": "# Runbook: high payment error rate\n\nAlert: `PaymentsErrorRateHigh` (more than 5% of payments failing for 5 minutes)\n\nLast reviewed on 2026-11-01 by the Payments team.\n\n## Impact\n\nCustomers cannot pay. Orders stay in \"waiting for payment\" and are cancelled after 30 minutes.\n\n## Diagnosis\n\n1. Open the **Payments – overview** dashboard and look at errors by type.\n2. If most errors are `provider_timeout`, check the provider status page.\n3. If most errors are `internal`, look at the deploys of the last hour.\n4. Search the logs:\n\n```bash\nlogs search 'service:payments level:error' --since 15m | head\n```\n\n## Actions\n\n1. **Provider down:** turn on the queue mode, so payments wait instead of failing:\n\n   ```bash\n   paymentsctl flags set queue-mode on\n   ```\n\n2. **Bad deploy:** roll back to the previous version:\n\n   ```bash\n   kubectl -n payments rollout undo deployment/payments\n   ```\n\n3. Confirm the error rate drops below 1% in the dashboard.\n\n## How to escalate\n\n- After 15 minutes without a fix: call the Payments team lead.\n- Provider down for more than 30 minutes: open a ticket with the provider (priority 1) and tell `#incidents`.\n\n## After it is solved\n\n- Turn off the queue mode, if you turned it on\n- Write down what happened in `#incidents`\n- Open a postmortem if customers were affected\n",
  "examples/en/docs/how-to-guides/troubleshooting.md": "# Troubleshooting\n\nThe problems people hit most often with the Payments Service, and how to solve them.\n\n## The payment stays in `pending`\n\n- **Probable cause:** the provider webhook did not arrive.\n- **How to confirm:** `paymentsctl show <id>` has no `provider_event`.\n- **How to fix:** `paymentsctl sync <id>` asks the provider for the current state.\n\n## \"Idempotency key reused with a different body\"\n\n- **Probable cause:** the client sent the same `Idempotency-Key` for a different payment.\n- **How to confirm:** the 422 answer lists both bodies.\n- **How to fix:** the client must create a new key for each new payment. See\n  [ADR 0003](../explanation/adr.md).\n\n## Local environment: `provider-sim` does not start\n\n- **Probable cause:** port 9090 is in use.\n- **How to confirm:** `docker compose logs provider-sim` says \"address already in use\".\n- **How to fix:** stop whatever uses the port, or set `PROVIDER_SIM_PORT` in `.env`.\n",
  "examples/en/docs/index.md": "# Payments Service (examples)\n\nThese pages show what each template of the [TechDocs Editor](https://marketplace.visualstudio.com/items?itemName=edtroleis.techdocs-editor)\nlooks like when it is filled in. They describe a fictional service, the **Payments Service**, that charges\ncustomers' cards through an external provider.\n\nThe pages follow [Diátaxis](https://diataxis.fr/), which sorts documentation by what the reader needs.\n\n## Tutorials\n\nFor when the reader wants to learn by doing, from zero.\n\n- [Your first payment](tutorials/tutorial.md)\n- [Onboarding](tutorials/onboarding.md)\n- [Golden path](tutorials/golden-path.md)\n\n## How-to guides\n\nFor when the reader wants to get a known task done.\n\n- [Rotate the API key](how-to-guides/guide.md)\n- [Refund a payment](how-to-guides/how-to.md)\n- [Runbook](how-to-guides/runbook.md)\n- [Troubleshooting](how-to-guides/troubleshooting.md)\n\n## Reference\n\nFor when the reader wants to look something up.\n\n- [Service home](reference/service-home.md)\n- [Operations](reference/operations.md)\n- [API](reference/api-reference.md)\n- [Wiki page](reference/wiki-page.md)\n- [Release notes](reference/release-notes.md)\n- [Glossary](reference/glossary.md)\n\n## Explanation\n\nFor when the reader wants to understand why.\n\n- [Architecture](explanation/architecture.md)\n- [ADR](explanation/adr.md)\n- [Postmortem](explanation/postmortem.md)\n- [RFC](explanation/rfc.md)\n\nEverything here is made up: names, numbers, links and people.\n",
  "examples/en/docs/reference/api-reference.md": "# Payments API\n\nThe HTTP API of the Payments Service, for services that need to charge a customer.\n\n## Overview\n\n- Base URL: `https://payments.internal.example.com`\n- JSON in and out; amounts in cents (`1000` = 10.00)\n\n## Authentication\n\nA service token in the `Authorization: Bearer <token>` header. Ask for one in `#payments-team`.\n\n## Endpoints\n\n### Create a payment\n\n`POST /v1/payments`\n\n| Field      | Type    | Required | Description                  |\n| ---------- | ------- | -------- | ---------------------------- |\n| `orderId`  | string  | yes      | The order being paid         |\n| `amount`   | integer | yes      | Amount in cents              |\n| `currency` | string  | yes      | ISO 4217 code, such as `USD` |\n| `card`     | string  | yes      | Card token from the checkout |\n\nThe `Idempotency-Key` header is required: the same key with the same body returns the same payment.\n\n```json\n{ \"id\": \"pay_123\", \"status\": \"pending\", \"amount\": 1000, \"currency\": \"USD\" }\n```\n\nErrors: `400` invalid field, `402` card declined, `422` idempotency key reused with another body.\n\n### Read a payment\n\n`GET /v1/payments/{id}`. Returns the payment, with `status` one of `pending`, `paid`, `failed`, `refunded`.\n\n## Limits\n\n100 requests per second per service. Above that: `429`, with `Retry-After`.\n\n## Versions\n\n`v1` is the current version. Breaking changes get a new version and six months of overlap.\n",
  "examples/en/docs/reference/glossary.md": "# Glossary\n\nTerms used in this documentation, in alphabetical order.\n\n## C\n\n### Capture\n\nTaking the money that an authorization reserved. The Payments Service authorizes and captures in one step.\n\n## I\n\n### Idempotency key\n\nA value the client sends so that repeating a request does not charge twice. See [ADR 0003](../explanation/adr.md).\n\n## P\n\n### Provider\n\nThe external company that talks to the card networks for us.\n\n## W\n\n### Webhook\n\nA call the provider makes to us when a payment changes state.\n",
  "examples/en/docs/reference/operations.md": "# Operations and support\n\nHow the Payments Service is run day to day.\n\n## On call and escalation\n\n- PagerDuty schedule \"Payments\", one week each, handover on Mondays at 10:00\n- Escalation: on-call engineer → team lead → head of engineering\n\n## SLOs\n\n| SLO                                      | Target | Window  |\n| ---------------------------------------- | ------ | ------- |\n| Payments created without error           | 99.9%  | 30 days |\n| Time to answer `POST /v1/payments` (p99) | 800 ms | 30 days |\n\n## Alerts\n\n| Alert                    | Runbook                                                |\n| ------------------------ | ------------------------------------------------------ |\n| `PaymentsErrorRateHigh`  | [High payment error rate](../how-to-guides/runbook.md) |\n| `PaymentsPendingTooLong` | [Troubleshooting](../how-to-guides/troubleshooting.md) |\n\n## Dashboards and logs\n\n- **Payments – overview:** traffic, errors and latency\n- **Payments – provider:** answers and timeouts from the provider\n- Logs: `service:payments`\n\n## Deploy and rollback\n\nEvery merge to `main` goes to staging. Production needs one approval in the pipeline. Rollback:\n`kubectl -n payments rollout undo deployment/payments`.\n\n## Maintenance\n\n- Rotate the provider API key every 90 days ([guide](../how-to-guides/guide.md))\n- Database: minor versions are applied by the platform team on Sundays\n",
  "examples/en/docs/reference/release-notes.md": "# Release notes\n\n## 2.4.0 (2026-11-10)\n\n### Added\n\n- Partial refunds: `paymentsctl refund --amount`\n\n### Changed\n\n- `POST /v1/payments` answers in 300 ms less (p99), after the database index change\n\n### Fixed\n\n- A payment could stay `pending` when the provider webhook arrived twice\n\n### Upgrade notes\n\nNothing to do for clients of the API.\n\n## 2.3.0 (2026-10-02)\n\n### Added\n\n- The queue mode for provider outages (see [RFC 0007](../explanation/rfc.md))\n",
  "examples/en/docs/reference/service-home.md": "# Payments Service\n\nCharges customers' cards for orders, through an external card provider, and tells the other services when a\npayment succeeds or fails.\n\n## Who takes care of it\n\n- **Team:** Payments\n- **Channel:** `#payments-team`\n- **On call:** PagerDuty schedule \"Payments\"\n\n## Links\n\n- [Repository](https://github.com/example/payments-service)\n- [Dashboards](https://grafana.example.com/d/payments)\n- [Catalog entry](https://backstage.example.com/catalog/default/component/payments-service)\n\n## Dependencies\n\n| Depends on    | For                                            |\n| ------------- | ---------------------------------------------- |\n| Card provider | Charging and refunding cards                   |\n| PostgreSQL    | Payments and refunds                           |\n| Event bus     | Publishing `payment.paid` and `payment.failed` |\n\n## How to start\n\n- New to the service: [Your first payment](../tutorials/tutorial.md)\n- Integrating with it: [Payments API](api-reference.md)\n- On call: [Operations and support](operations.md)\n",
  "examples/en/docs/reference/wiki-page.md": "# Team rituals\n\nHow the Payments team works week to week.\n\n## Summary\n\nPlanning on Mondays, a short daily, and a review every other Friday.\n\n## Content\n\n| Ritual   | When                     | How long | What for                    |\n| -------- | ------------------------ | -------- | --------------------------- |\n| Planning | Monday 10:30             | 45 min   | Choose the work of the week |\n| Daily    | Every day 9:45           | 15 min   | Unblock each other          |\n| Review   | Every other Friday 15:00 | 30 min   | Show what shipped           |\n| Retro    | Last Friday of the month | 45 min   | Improve how we work         |\n\nMeetings are optional for whoever is on call.\n\n## Related links\n\n- [Onboarding](../tutorials/onboarding.md)\n- [Operations and support](operations.md)\n\n## Last review\n\n2026-11-01, by the team lead.\n",
  "examples/en/docs/tutorials/golden-path.md": "# Golden path: a new backend service\n\nThe recommended way to create a backend service at Example Corp: Kotlin, Spring Boot, PostgreSQL and the\nstandard deploy pipeline. The Payments Service was created this way.\n\n## When to use it (and when not)\n\n- **Use it** for an HTTP service that owns its data and runs on the platform cluster.\n- **Do not use it** for batch jobs (see the data golden path) or for front-ends.\n\n## What you get\n\n- A repository with build, tests, linting and security scans already set up\n- Deploy to staging on every merge and to production with one approval\n- Dashboards, alerts and logs that work from day one\n- A TechDocs site and a `catalog-info.yaml`\n\n## Before you start\n\n- A team in the catalog that will own the service\n- A name for the service, in kebab case (`payments-service`)\n\n## Steps\n\n1. In Backstage, open **Create** and choose **Backend service (Kotlin)**.\n2. Fill in the name, the owner team and a one-line description. Click **Create**.\n3. Open the new repository and merge the first pull request the template opened.\n4. Wait for the pipeline: the service shows up in staging in about 10 minutes.\n5. Open the service in the catalog and check the **Docs** tab.\n\n## Owner of the golden path\n\nThe Platform team, in `#platform-help`.\n\n## Alternatives\n\n- Data jobs: the data golden path\n- Front-ends: the web golden path\n",
  "examples/en/docs/tutorials/onboarding.md": "# Onboarding: Payments team\n\nWelcome to the Payments team. This page takes you through your first week. Ask anything in `#payments-team`:\nthere are no silly questions here.\n\n## Access to request\n\n| What                           | Where                            | Who approves |\n| ------------------------------ | -------------------------------- | ------------ |\n| GitHub team `payments`         | Access portal, \"GitHub teams\"    | Team lead    |\n| Provider dashboard (read only) | Ticket to Finance Ops            | Finance Ops  |\n| Production logs                | Access portal, \"Logs – payments\" | Team lead    |\n| On-call schedule               | PagerDuty, after your third week | Team lead    |\n\n## Local environment\n\nFollow [Your first payment](tutorial.md). When the test charge says `paid`, your environment is ready.\n\n## First task\n\nPick an issue labeled `good first issue` in the `payments-service` repository. Pair with your buddy on the\nfirst pull request: they will show you how we review and deploy.\n\n## People and channels\n\n- **Team lead:** Ana Souza\n- **Your buddy:** assigned on your first day\n- `#payments-team`: daily work and questions\n- `#payments-alerts`: alerts (read, do not act until you are on call)\n\n## Team glossary\n\nSee the [Glossary](../reference/glossary.md).\n",
  "examples/en/docs/tutorials/tutorial.md": "# Your first payment\n\nIn this tutorial you charge a test card through the Payments Service running on your machine, and see the\npayment go from `pending` to `paid`. It takes about 20 minutes.\n\n## What you will build\n\nA local Payments Service, a test charge of 10.00 USD, and the event that tells the order service the charge\nworked.\n\n## Before you start\n\n- Docker and Docker Compose\n- `curl` and `jq`\n- Access to the `payments-service` repository\n\n## Steps\n\n1. Clone the repository and start the service with its database and the provider simulator:\n\n   ```bash\n   git clone https://github.com/example/payments-service.git\n   cd payments-service\n   docker compose up -d\n   ```\n\n   You should see three containers running: `payments`, `postgres` and `provider-sim`.\n\n2. Create a payment:\n\n   ```bash\n   curl -s -X POST localhost:8080/v1/payments \\\n      -H 'Idempotency-Key: tutorial-1' \\\n      -d '{\"orderId\": \"order-1\", \"amount\": 1000, \"currency\": \"USD\", \"card\": \"4242424242424242\"}' | jq\n   ```\n\n   The answer has `\"status\": \"pending\"` and an `id` that starts with `pay_`.\n\n3. Wait two seconds and read it again:\n\n   ```bash\n   curl -s localhost:8080/v1/payments/<id> | jq .status\n   ```\n\n   It now says `\"paid\"`: the simulator approved the card.\n\n4. Look at the event the service published:\n\n   ```bash\n   docker compose logs payments | grep payment.paid\n   ```\n\n   The order service listens to this event to ship the order.\n\n## What you learned\n\nYou created a payment, saw it change state asynchronously and found the event other services use.\n\n## Next steps\n\n- [Refund a payment](../how-to-guides/how-to.md)\n- [How the service is built](../explanation/architecture.md)\n",
  "examples/en/mkdocs.yml": "site_name: Payments Service (examples)\nsite_description: Example pages for every template, filled in for a fictional payments service\nnav:\n  - Home: index.md\n  - Tutorials:\n      - Your first payment: tutorials/tutorial.md\n      - Onboarding: tutorials/onboarding.md\n      - Golden path for a new service: tutorials/golden-path.md\n  - How-to guides:\n      - Rotate the provider API key: how-to-guides/guide.md\n      - Refund a payment: how-to-guides/how-to.md\n      - \"Runbook: high payment error rate\": how-to-guides/runbook.md\n      - Troubleshooting: how-to-guides/troubleshooting.md\n  - Reference:\n      - Payments Service: reference/service-home.md\n      - Operations and support: reference/operations.md\n      - Payments API: reference/api-reference.md\n      - Team wiki page: reference/wiki-page.md\n      - Release notes: reference/release-notes.md\n      - Glossary: reference/glossary.md\n  - Explanation:\n      - Architecture: explanation/architecture.md\n      - \"ADR 0003: idempotency keys\": explanation/adr.md\n      - \"Postmortem: duplicate charges\": explanation/postmortem.md\n      - \"RFC 0007: retries with a queue\": explanation/rfc.md\nplugins:\n  - techdocs-core\nmarkdown_extensions:\n  - pymdownx.superfences:\n      custom_fences:\n        - name: mermaid\n          class: mermaid\n          format: !!python/name:pymdownx.superfences.fence_code_format\n",
  "examples/pt-br/docs/explanation/adr.md": "# ADR 0003: chaves de idempotência na criação de pagamentos\n\nStatus: Aceito\n\nData: 2026-03-14\n\n## Contexto\n\nOs clientes repetem o `POST /v1/payments` quando a rede falha. Sem proteção, uma repetição depois de uma resposta\nlenta criava um segundo pagamento e cobrava o cliente duas vezes (veja o [postmortem](postmortem.md)).\n\n## Decisão\n\nO `POST /v1/payments` exige o cabeçalho `Idempotency-Key`. O serviço guarda a chave com o corpo da requisição por\n24 horas. A mesma chave com o mesmo corpo devolve o primeiro pagamento; com outro corpo, responde `422`.\n\n## Consequências\n\n- Repetir é seguro para os clientes.\n- Todos os clientes precisaram mudar para mandar o cabeçalho (feito no 2º trimestre).\n- A tabela de chaves cresce; um job apaga as chaves com mais de 24 horas.\n\n## Alternativas consideradas\n\n- **Evitar repetição pelo id do pedido:** não permite dois pagamentos para um pedido (pagamento dividido).\n- **Pedir ao provedor para evitar repetições:** o provedor só oferece isso por 1 hora.\n",
  "examples/pt-br/docs/explanation/architecture.md": "# Arquitetura\n\nComo o Serviço de Pagamentos é construído hoje, e por quê.\n\n## Contexto\n\nO checkout chama o Serviço de Pagamentos para cobrar um pedido. O serviço fala com o provedor de cartões e avisa\no serviço de pedidos do resultado pelo barramento de eventos.\n\n## Visão geral\n\n```mermaid\nflowchart LR\n  Checkout -->|POST /v1/payments| API[API de Pagamentos]\n  API --> DB[(PostgreSQL)]\n  API --> Provedor[Provedor de cartões]\n  Provedor -->|webhook| API\n  API -->|payment.paid| Bus[Barramento de eventos]\n  Bus --> Pedidos[Serviço de pedidos]\n```\n\n## Componentes\n\n- **API:** recebe os pagamentos, guarda e chama o provedor\n- **Receptor de webhooks:** recebe as respostas do provedor e atualiza o pagamento\n- **Job de sincronização:** a cada 5 minutos, pergunta ao provedor sobre pagamentos em `pending` há muito tempo\n\n## Dados\n\nUma tabela para pagamentos e uma para estornos. Números de cartão nunca chegam ao nosso banco: o checkout manda\num token.\n\n## Integrações\n\n| Sistema               | Como             | Por quê                   |\n| --------------------- | ---------------- | ------------------------- |\n| Provedor de cartões   | HTTPS e webhooks | Cobrar e estornar         |\n| Barramento de eventos | Publicação       | Avisar os outros serviços |\n\n## Decisões importantes\n\n- [ADR 0003: chaves de idempotência](adr.md)\n- [RFC 0007: novas tentativas com fila](rfc.md)\n\n## Riscos conhecidos\n\n- O provedor é um ponto único de falha; o modo fila só adia os pagamentos.\n",
  "examples/pt-br/docs/explanation/postmortem.md": "# Postmortem: cobranças em dobro em 2026-03-02\n\nUma revisão sem culpados. O objetivo é aprender, não achar culpados.\n\n## Resumo\n\nPor 40 minutos, 312 clientes foram cobrados duas vezes. Todos foram reembolsados no mesmo dia.\n\n## Impacto\n\n- 312 cobranças em dobro, 18.400 BRL no total, estornadas até as 18:00\n- 47 chamados no atendimento\n\n## Linha do tempo\n\n| Hora  | O que aconteceu                                                |\n| ----- | -------------------------------------------------------------- |\n| 14:05 | O provedor passa a responder em 20 s em vez de 1 s             |\n| 14:06 | O checkout desiste em 10 s e repete o pagamento                |\n| 14:20 | O atendimento avisa de clientes cobrados duas vezes            |\n| 14:45 | Repetições do checkout desligadas; as cobranças em dobro param |\n| 18:00 | Último estorno feito                                           |\n\n## Causa raiz\n\nO checkout repetia os pagamentos depois de um timeout, e o Serviço de Pagamentos não tinha como diferenciar uma\nrepetição de um pagamento novo.\n\n## O que funcionou e o que não\n\n- Funcionou: os estornos tinham script e terminaram no mesmo dia.\n- Não funcionou: não havia alerta de cobrança em dobro; o atendimento soube primeiro.\n\n## Ações\n\n| Ação                                                     | Dono       | Prazo      |\n| -------------------------------------------------------- | ---------- | ---------- |\n| Chaves de idempotência ([ADR 0003](adr.md))              | Pagamentos | 2026-04-15 |\n| Alerta para dois pagamentos do mesmo pedido em 5 minutos | Pagamentos | 2026-03-20 |\n",
  "examples/pt-br/docs/explanation/rfc.md": "# RFC 0007: novas tentativas com fila quando o provedor cai\n\nStatus: Aceita\n\nAutor: time de Pagamentos · Data: 2026-08-20\n\n## Resumo\n\nQuando o provedor de cartões está fora do ar, guardar os pagamentos novos numa fila e cobrar quando ele voltar,\nem vez de falhar na hora.\n\n## Problema\n\nNas três quedas do provedor este ano, todos os pagamentos falharam e os clientes tiveram de recomeçar. Uns 30%\nnão voltaram.\n\n## Proposta\n\nUma flag `queue mode`. Ligada, o `POST /v1/payments` guarda o pagamento como `pending` e responde na hora; um\nworker cobra a fila quando o provedor volta a responder, do mais antigo para o mais novo.\n\n```mermaid\nflowchart LR\n  A[Pagamento novo] --> B{Modo fila?}\n  B -- Não --> C[Cobrar agora]\n  B -- Sim --> D[Guardar como pending]\n  D --> E[Worker cobra depois]\n```\n\n## Alternativas\n\n| Opção            | Prós                   | Contras                            |\n| ---------------- | ---------------------- | ---------------------------------- |\n| Modo fila        | Clientes não recomeçam | Pedidos esperam; mais código       |\n| Segundo provedor | Sem espera             | Contrato, custo, meses de trabalho |\n| Não fazer nada   | Nenhum trabalho        | Vendas perdidas a cada queda       |\n\n## Riscos e perguntas em aberto\n\n- Um cartão pode ser recusado horas depois: o serviço de pedidos precisa tratar `payment.failed` atrasado.\n  (Respondido: ele trata.)\n- Por quanto tempo guardar os pagamentos na fila: 2 horas, depois falham.\n\n## Implantação\n\nAtrás da flag, ligada à mão pelo runbook. Saiu na 2.3.0.\n",
  "examples/pt-br/docs/how-to-guides/guide.md": "# Trocar a chave da API do provedor\n\nEste guia mostra como trocar a chave que o Serviço de Pagamentos usa para falar com o provedor de cartões, sem\ndeixar o serviço fora do ar. Faça a cada 90 dias, ou na hora se a chave vazar.\n\n## Objetivo\n\nO serviço usa uma chave nova, e a antiga é revogada.\n\n## Antes de começar\n\n- Acesso de administrador ao painel do provedor\n- Permissão de escrita no segredo `payments/provider` do cofre\n- Um momento tranquilo: evite o primeiro e o último dia do mês\n\n## Passos\n\n1. No painel do provedor, abra **API keys** e crie uma chave nova chamada `payments-<data>`.\n\n2. Guarde a chave no cofre como a **secundária**:\n\n   ```bash\n   vault kv patch secret/payments/provider secondary_key=<chave nova>\n   ```\n\n3. Reinicie o serviço. Ele tenta a chave primária e, se falhar, a secundária:\n\n   ```bash\n   kubectl -n payments rollout restart deployment/payments\n   ```\n\n4. Troque as chaves no cofre: a nova vira `primary_key`, e a antiga sai.\n\n5. Reinicie o serviço de novo e revogue a chave antiga no painel do provedor.\n\n## Como conferir que deu certo\n\nNo dashboard **Payments – provider**, os erros de autenticação continuam em zero e a taxa de aprovação não cai.\n\n## Problemas comuns\n\n- **401 do provedor depois do passo 5:** a chave antiga foi revogada antes de o reinício terminar. Volte com ela\n  como `secondary_key` e reinicie.\n",
  "examples/pt-br/docs/how-to-guides/how-to.md": "# Estornar um pagamento\n\nComo estornar um pagamento, inteiro ou em parte, pela linha de comando.\n\n## Passos\n\n1. Ache o pagamento pelo pedido:\n\n   ```bash\n   paymentsctl find --order pedido-1\n   ```\n\n2. Estorne. Sem `--amount`, estorna tudo:\n\n   ```bash\n   paymentsctl refund pay_123 --amount 500 --reason \"produto avariado\"\n   ```\n\n3. Passe para o atendimento o id do estorno (começa com `ref_`).\n\n## Como conferir que deu certo\n\n`paymentsctl show pay_123` mostra o estorno com status `succeeded`. O dinheiro chega ao cliente em 5 a 10 dias\núteis.\n",
  "examples/pt-br/docs/how-to-guides/runbook.md": "# Runbook: muitos pagamentos com erro\n\nAlerta: `PaymentsErrorRateHigh` (mais de 5% dos pagamentos falhando por 5 minutos)\n\nRevisado em 2026-11-01 pelo time de Pagamentos.\n\n## Impacto\n\nOs clientes não conseguem pagar. Os pedidos ficam em \"aguardando pagamento\" e são cancelados depois de 30\nminutos.\n\n## Diagnóstico\n\n1. Abra o dashboard **Payments – overview** e veja os erros por tipo.\n2. Se a maioria é `provider_timeout`, confira a página de status do provedor.\n3. Se a maioria é `internal`, veja os deploys da última hora.\n4. Busque nos logs:\n\n```bash\nlogs search 'service:payments level:error' --since 15m | head\n```\n\n## Ações\n\n1. **Provedor fora do ar:** ligue o modo fila, para os pagamentos esperarem em vez de falhar:\n\n   ```bash\n   paymentsctl flags set queue-mode on\n   ```\n\n2. **Deploy com problema:** volte para a versão anterior:\n\n   ```bash\n   kubectl -n payments rollout undo deployment/payments\n   ```\n\n3. Confirme no dashboard que a taxa de erro caiu para menos de 1%.\n\n## Como escalar\n\n- Depois de 15 minutos sem resolver: ligue para o líder do time de Pagamentos.\n- Provedor fora do ar por mais de 30 minutos: abra um chamado com o provedor (prioridade 1) e avise em\n  `#incidents`.\n\n## Depois de resolver\n\n- Desligue o modo fila, se ligou\n- Registre o que aconteceu em `#incidents`\n- Abra um postmortem se algum cliente foi afetado\n",
  "examples/pt-br/docs/how-to-guides/troubleshooting.md": "# Solução de problemas\n\nOs problemas mais comuns com o Serviço de Pagamentos, e como resolver.\n\n## O pagamento fica em `pending`\n\n- **Causa provável:** o webhook do provedor não chegou.\n- **Como confirmar:** `paymentsctl show <id>` não tem `provider_event`.\n- **Como resolver:** `paymentsctl sync <id>` pergunta ao provedor o estado atual.\n\n## \"Idempotency key reused with a different body\"\n\n- **Causa provável:** o cliente mandou a mesma `Idempotency-Key` para outro pagamento.\n- **Como confirmar:** a resposta 422 mostra os dois corpos.\n- **Como resolver:** o cliente precisa criar uma chave nova para cada pagamento novo. Veja o\n  [ADR 0003](../explanation/adr.md).\n\n## Ambiente local: o `provider-sim` não sobe\n\n- **Causa provável:** a porta 9090 está em uso.\n- **Como confirmar:** `docker compose logs provider-sim` diz \"address already in use\".\n- **Como resolver:** pare o que está usando a porta, ou defina `PROVIDER_SIM_PORT` no `.env`.\n",
  "examples/pt-br/docs/index.md": "# Serviço de Pagamentos (exemplos)\n\nEstas páginas mostram como fica cada template do [TechDocs Editor](https://marketplace.visualstudio.com/items?itemName=edtroleis.techdocs-editor)\ndepois de preenchido. Elas descrevem um serviço fictício, o **Serviço de Pagamentos**, que cobra os cartões dos\nclientes por meio de um provedor externo.\n\nAs páginas seguem o [Diátaxis](https://diataxis.fr/), que separa a documentação pelo que o leitor precisa.\n\n## Tutoriais\n\nPara quando o leitor quer aprender fazendo, do zero.\n\n- [Seu primeiro pagamento](tutorials/tutorial.md)\n- [Onboarding](tutorials/onboarding.md)\n- [Golden path](tutorials/golden-path.md)\n\n## Guias\n\nPara quando o leitor quer fazer uma tarefa conhecida.\n\n- [Trocar a chave da API](how-to-guides/guide.md)\n- [Estornar um pagamento](how-to-guides/how-to.md)\n- [Runbook](how-to-guides/runbook.md)\n- [Solução de problemas](how-to-guides/troubleshooting.md)\n\n## Referência\n\nPara quando o leitor quer consultar.\n\n- [Página inicial](reference/service-home.md)\n- [Operação](reference/operations.md)\n- [API](reference/api-reference.md)\n- [Página da wiki](reference/wiki-page.md)\n- [Notas de versão](reference/release-notes.md)\n- [Glossário](reference/glossary.md)\n\n## Explicação\n\nPara quando o leitor quer entender o porquê.\n\n- [Arquitetura](explanation/architecture.md)\n- [ADR](explanation/adr.md)\n- [Postmortem](explanation/postmortem.md)\n- [RFC](explanation/rfc.md)\n\nTudo aqui é inventado: nomes, números, links e pessoas.\n",
  "examples/pt-br/docs/reference/api-reference.md": "# API de Pagamentos\n\nA API HTTP do Serviço de Pagamentos, para os serviços que precisam cobrar um cliente.\n\n## Visão geral\n\n- URL base: `https://payments.internal.example.com`\n- JSON na entrada e na saída; valores em centavos (`1000` = 10,00)\n\n## Autenticação\n\nUm token de serviço no cabeçalho `Authorization: Bearer <token>`. Peça um em `#payments-team`.\n\n## Endpoints\n\n### Criar um pagamento\n\n`POST /v1/payments`\n\n| Campo      | Tipo    | Obrigatório | Descrição                         |\n| ---------- | ------- | ----------- | --------------------------------- |\n| `orderId`  | string  | sim         | O pedido que está sendo pago      |\n| `amount`   | integer | sim         | Valor em centavos                 |\n| `currency` | string  | sim         | Código ISO 4217, como `BRL`       |\n| `card`     | string  | sim         | Token do cartão vindo do checkout |\n\nO cabeçalho `Idempotency-Key` é obrigatório: a mesma chave com o mesmo corpo devolve o mesmo pagamento.\n\n```json\n{ \"id\": \"pay_123\", \"status\": \"pending\", \"amount\": 1000, \"currency\": \"BRL\" }\n```\n\nErros: `400` campo inválido, `402` cartão recusado, `422` chave de idempotência reaproveitada com outro corpo.\n\n### Ler um pagamento\n\n`GET /v1/payments/{id}`. Devolve o pagamento, com `status` igual a `pending`, `paid`, `failed` ou `refunded`.\n\n## Limites\n\n100 requisições por segundo por serviço. Acima disso: `429`, com `Retry-After`.\n\n## Versões\n\n`v1` é a versão atual. Mudanças incompatíveis ganham uma versão nova e seis meses de convivência.\n",
  "examples/pt-br/docs/reference/glossary.md": "# Glossário\n\nTermos usados nesta documentação, em ordem alfabética.\n\n## C\n\n### Captura\n\nPegar o dinheiro que uma autorização reservou. O Serviço de Pagamentos autoriza e captura num passo só.\n\n### Chave de idempotência\n\nUm valor que o cliente manda para que repetir uma requisição não cobre duas vezes. Veja o [ADR 0003](../explanation/adr.md).\n\n## P\n\n### Provedor\n\nA empresa externa que fala com as bandeiras de cartão por nós.\n\n## W\n\n### Webhook\n\nUma chamada que o provedor faz para nós quando um pagamento muda de estado.\n",
  "examples/pt-br/docs/reference/operations.md": "# Operação e suporte\n\nComo o Serviço de Pagamentos é operado no dia a dia.\n\n## Plantão e escalonamento\n\n- Escala \"Payments\" no PagerDuty, uma semana para cada pessoa, troca às segundas às 10:00\n- Escalonamento: pessoa de plantão → líder do time → head de engenharia\n\n## SLOs\n\n| SLO                                            | Meta   | Janela  |\n| ---------------------------------------------- | ------ | ------- |\n| Pagamentos criados sem erro                    | 99,9%  | 30 dias |\n| Tempo de resposta do `POST /v1/payments` (p99) | 800 ms | 30 dias |\n\n## Alertas\n\n| Alerta                   | Runbook                                                     |\n| ------------------------ | ----------------------------------------------------------- |\n| `PaymentsErrorRateHigh`  | [Muitos pagamentos com erro](../how-to-guides/runbook.md)   |\n| `PaymentsPendingTooLong` | [Solução de problemas](../how-to-guides/troubleshooting.md) |\n\n## Dashboards e logs\n\n- **Payments – overview:** tráfego, erros e latência\n- **Payments – provider:** respostas e timeouts do provedor\n- Logs: `service:payments`\n\n## Deploy e rollback\n\nTodo merge na `main` vai para staging. Produção precisa de uma aprovação na pipeline. Rollback:\n`kubectl -n payments rollout undo deployment/payments`.\n\n## Manutenção\n\n- Trocar a chave da API do provedor a cada 90 dias ([guia](../how-to-guides/guide.md))\n- Banco de dados: versões menores aplicadas pelo time de plataforma aos domingos\n",
  "examples/pt-br/docs/reference/release-notes.md": "# Notas de versão\n\n## 2.4.0 (2026-11-10)\n\n### Novidades\n\n- Estornos parciais: `paymentsctl refund --amount`\n\n### Mudanças\n\n- O `POST /v1/payments` responde 300 ms mais rápido (p99), depois da mudança de índice no banco\n\n### Correções\n\n- Um pagamento podia ficar em `pending` quando o webhook do provedor chegava duas vezes\n\n### Como atualizar\n\nNada a fazer para quem usa a API.\n\n## 2.3.0 (2026-10-02)\n\n### Novidades\n\n- O modo fila para quando o provedor cai (veja a [RFC 0007](../explanation/rfc.md))\n",
  "examples/pt-br/docs/reference/service-home.md": "# Serviço de Pagamentos\n\nCobra os cartões dos clientes pelos pedidos, por meio de um provedor de cartões externo, e avisa os outros\nserviços quando um pagamento dá certo ou falha.\n\n## Quem cuida\n\n- **Time:** Pagamentos\n- **Canal:** `#payments-team`\n- **Plantão:** escala \"Payments\" no PagerDuty\n\n## Links\n\n- [Repositório](https://github.com/example/payments-service)\n- [Dashboards](https://grafana.example.com/d/payments)\n- [Entrada no catálogo](https://backstage.example.com/catalog/default/component/payments-service)\n\n## Dependências\n\n| Depende de            | Para                                       |\n| --------------------- | ------------------------------------------ |\n| Provedor de cartões   | Cobrar e estornar cartões                  |\n| PostgreSQL            | Pagamentos e estornos                      |\n| Barramento de eventos | Publicar `payment.paid` e `payment.failed` |\n\n## Como começar\n\n- Novo no serviço: [Seu primeiro pagamento](../tutorials/tutorial.md)\n- Integrando com ele: [API de Pagamentos](api-reference.md)\n- De plantão: [Operação e suporte](operations.md)\n",
  "examples/pt-br/docs/reference/wiki-page.md": "# Rituais do time\n\nComo o time de Pagamentos trabalha semana a semana.\n\n## Resumo\n\nPlanejamento às segundas, uma daily curta e uma review a cada duas sextas.\n\n## Conteúdo\n\n| Ritual       | Quando                               | Duração | Para quê                      |\n| ------------ | ------------------------------------ | ------- | ----------------------------- |\n| Planejamento | Segunda 10:30                        | 45 min  | Escolher o trabalho da semana |\n| Daily        | Todo dia 9:45                        | 15 min  | Destravar uns aos outros      |\n| Review       | Sexta, semana sim, semana não, 15:00 | 30 min  | Mostrar o que foi entregue    |\n| Retro        | Última sexta do mês                  | 45 min  | Melhorar o jeito de trabalhar |\n\nAs reuniões são opcionais para quem está de plantão.\n\n## Links relacionados\n\n- [Onboarding](../tutorials/onboarding.md)\n- [Operação e suporte](operations.md)\n\n## Última revisão\n\n2026-11-01, pelo líder do time.\n",
  "examples/pt-br/docs/tutorials/golden-path.md": "# Golden path: um serviço de backend novo\n\nO jeito recomendado de criar um serviço de backend na Example Corp: Kotlin, Spring Boot, PostgreSQL e a\npipeline de deploy padrão. O Serviço de Pagamentos foi criado assim.\n\n## Quando usar (e quando não)\n\n- **Use** para um serviço HTTP que é dono dos seus dados e roda no cluster da plataforma.\n- **Não use** para jobs em lote (veja o golden path de dados) nem para front-ends.\n\n## O que você ganha\n\n- Um repositório com build, testes, lint e varredura de segurança já configurados\n- Deploy em staging a cada merge e em produção com uma aprovação\n- Dashboards, alertas e logs funcionando desde o primeiro dia\n- Um site do TechDocs e um `catalog-info.yaml`\n\n## Antes de começar\n\n- Um time no catálogo que vai ser dono do serviço\n- Um nome para o serviço, em kebab case (`payments-service`)\n\n## Passos\n\n1. No Backstage, abra **Create** e escolha **Serviço de backend (Kotlin)**.\n2. Preencha o nome, o time dono e uma descrição de uma linha. Clique em **Create**.\n3. Abra o repositório novo e faça o merge do primeiro pull request que o template abriu.\n4. Espere a pipeline: o serviço aparece em staging em uns 10 minutos.\n5. Abra o serviço no catálogo e confira a aba **Docs**.\n\n## Dono do golden path\n\nO time de Plataforma, em `#platform-help`.\n\n## Alternativas\n\n- Jobs de dados: o golden path de dados\n- Front-ends: o golden path web\n",
  "examples/pt-br/docs/tutorials/onboarding.md": "# Onboarding: time de Pagamentos\n\nBoas-vindas ao time de Pagamentos. Esta página acompanha a sua primeira semana. Pergunte qualquer coisa em\n`#payments-team`: aqui não existe pergunta boba.\n\n## Acessos a pedir\n\n| O quê                           | Onde                                 | Quem aprova   |\n| ------------------------------- | ------------------------------------ | ------------- |\n| Time `payments` no GitHub       | Portal de acessos, \"Times do GitHub\" | Líder do time |\n| Painel do provedor (só leitura) | Chamado para Finance Ops             | Finance Ops   |\n| Logs de produção                | Portal de acessos, \"Logs – payments\" | Líder do time |\n| Escala de plantão               | PagerDuty, depois da terceira semana | Líder do time |\n\n## Ambiente local\n\nSiga [Seu primeiro pagamento](tutorial.md). Quando a cobrança de teste disser `paid`, o ambiente está pronto.\n\n## Primeira tarefa\n\nEscolha uma issue com a etiqueta `good first issue` no repositório `payments-service`. Faça o primeiro pull\nrequest em par com a sua dupla: ela mostra como revisamos e publicamos.\n\n## Pessoas e canais\n\n- **Líder do time:** Ana Souza\n- **Sua dupla:** definida no primeiro dia\n- `#payments-team`: trabalho do dia a dia e dúvidas\n- `#payments-alerts`: alertas (leia, mas só aja quando estiver de plantão)\n\n## Glossário do time\n\nVeja o [Glossário](../reference/glossary.md).\n",
  "examples/pt-br/docs/tutorials/tutorial.md": "# Seu primeiro pagamento\n\nNeste tutorial você cobra um cartão de teste pelo Serviço de Pagamentos rodando na sua máquina e vê o\npagamento passar de `pending` para `paid`. Leva uns 20 minutos.\n\n## O que você vai construir\n\nUm Serviço de Pagamentos local, uma cobrança de teste de 10,00 BRL e o evento que avisa o serviço de pedidos\nque a cobrança deu certo.\n\n## Antes de começar\n\n- Docker e Docker Compose\n- `curl` e `jq`\n- Acesso ao repositório `payments-service`\n\n## Passos\n\n1. Clone o repositório e suba o serviço com o banco de dados e o simulador do provedor:\n\n   ```bash\n   git clone https://github.com/example/payments-service.git\n   cd payments-service\n   docker compose up -d\n   ```\n\n   Você deve ver três containers rodando: `payments`, `postgres` e `provider-sim`.\n\n2. Crie um pagamento:\n\n   ```bash\n   curl -s -X POST localhost:8080/v1/payments \\\n      -H 'Idempotency-Key: tutorial-1' \\\n      -d '{\"orderId\": \"pedido-1\", \"amount\": 1000, \"currency\": \"BRL\", \"card\": \"4242424242424242\"}' | jq\n   ```\n\n   A resposta tem `\"status\": \"pending\"` e um `id` que começa com `pay_`.\n\n3. Espere dois segundos e leia de novo:\n\n   ```bash\n   curl -s localhost:8080/v1/payments/<id> | jq .status\n   ```\n\n   Agora diz `\"paid\"`: o simulador aprovou o cartão.\n\n4. Veja o evento que o serviço publicou:\n\n   ```bash\n   docker compose logs payments | grep payment.paid\n   ```\n\n   O serviço de pedidos escuta esse evento para enviar o pedido.\n\n## O que você aprendeu\n\nVocê criou um pagamento, viu o estado mudar sem esperar a resposta e achou o evento que os outros serviços usam.\n\n## Próximos passos\n\n- [Estornar um pagamento](../how-to-guides/how-to.md)\n- [Como o serviço é construído](../explanation/architecture.md)\n",
  "examples/pt-br/mkdocs.yml": "site_name: Serviço de Pagamentos (exemplos)\nsite_description: Páginas de exemplo de cada template, preenchidas para um serviço de pagamentos fictício\nnav:\n  - Início: index.md\n  - Tutoriais:\n      - Seu primeiro pagamento: tutorials/tutorial.md\n      - Onboarding: tutorials/onboarding.md\n      - Golden path de um serviço novo: tutorials/golden-path.md\n  - Guias:\n      - Trocar a chave da API do provedor: how-to-guides/guide.md\n      - Estornar um pagamento: how-to-guides/how-to.md\n      - \"Runbook: muitos pagamentos com erro\": how-to-guides/runbook.md\n      - Solução de problemas: how-to-guides/troubleshooting.md\n  - Referência:\n      - Serviço de Pagamentos: reference/service-home.md\n      - Operação e suporte: reference/operations.md\n      - API de Pagamentos: reference/api-reference.md\n      - Página da wiki do time: reference/wiki-page.md\n      - Notas de versão: reference/release-notes.md\n      - Glossário: reference/glossary.md\n  - Explicação:\n      - Arquitetura: explanation/architecture.md\n      - \"ADR 0003: chaves de idempotência\": explanation/adr.md\n      - \"Postmortem: cobranças em dobro\": explanation/postmortem.md\n      - \"RFC 0007: novas tentativas com fila\": explanation/rfc.md\nplugins:\n  - techdocs-core\nmarkdown_extensions:\n  - pymdownx.superfences:\n      custom_fences:\n        - name: mermaid\n          class: mermaid\n          format: !!python/name:pymdownx.superfences.fence_code_format\n"
};
